INSERT INTO `pctz_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1978, 1, '2025-06-30 09:42:48', '2025-06-30 04:12:48', '<strong>ఇందిరమ్మ ఇండ్ల పేరుతో అక్రమ వసూలకు పాల్పడితే కఠిన చర్యలు తీసుకుంటాం--యాదాద్రి భువనగిరి జిల్లా కలెక్టర్ హనుమంతరావు</strong>\r\n\r\n<strong>NTODAY NEWS:</strong> యాదాద్రి భువనగిరి జిల్లా\r\n\r\nభువనగిరి పట్టణంలోని 18 వార్డు లో వార్డు ఆఫీసర్ పేరు చెప్పి ఇందిరమ్మ ఇండ్ల నిర్మాణపు పనులకు గాను అందే నరేష్ 20 వేలు వసూలు చేయడం జరిగిందని అభియోగం వచ్చినందున అట్టి విషయంపై అతనిపై క్రిమినల్ కేసు నమోదు చేయడం జరిగిందని యాదాద్రి భువనగిరి జిల్లా కలెక్టర్ హనుమంతరావు తెలిపారు.ఇందిరమ్మ ఇండ్లు మరియు ప్రభుత్వ సంక్షేమ పథకాల వంటి వాటిని ఇప్పిస్తామని లబ్ధిదారుల నుంచి డబ్బులు వసూలు చేసినట్లయితే అట్టి వారిపై చట్టపరమైన చర్యలతో పాటు, క్రిమినల్ కేసులు పెట్టడం జరుగుతుందని కలెక్టర్ స్పష్టం చేశారు. లబ్ధిదారులు ఇందిరమ్మ ఇల్లు ఇప్పిస్తామని చెప్పే దళారుల మాట నమ్మవద్దని అలా ఎవరైనా వస్తే తమ దృష్టికి తీసుకొని రావాలని, అట్టి వారిపై క్రిమినల్ కేసులు నమోదు చేయడం జరుగుతుందని తెలిపారు. ఇందిరమ్మ ఇండ్ల పంపిణీ పారదర్శకంగా జరుగుతుందని దళారులను నమ్మొద్దని ఇందిరమ్మ ఇండ్లు కట్టుకునేందుకు ప్రభుత్వం 5 లక్షలు సహాయం అందిస్తుందని, ఎవరైన ఇందిరమ్మ ఇండ్లు ఇప్పిస్తామని చెప్పిన వారిని నమ్మోదని కలెక్టర్ తెలిపారు.\r\n\r\nFollow us on\r\n<a href=\"https://ntodaynews.com/\">Website</a>\r\n<a href=\"https://www.facebook.com/share/156vzUPBsQ/\">Facebook</a>\r\n<a href=\"https://www.instagram.com/ntoday_news?utm_source=qr&amp;igsh=bHp0M2x5dTIydXYy\">Instagram</a>\r\n<a href=\"https://youtube.com/@ntodaynews?si=XcGJOnHJ2MGzT0MF\">YouTube</a>', 'అక్రమ వసూలకు పాల్పడితే కఠిన చర్యలు తీసుకుంటాం', '', 'publish', 'open', 'open', '', 'strict-action-will-be-taken-against-those-involved-in-illegal-collection', '', '', '2025-06-30 09:44:20', '2025-06-30 04:14:20', '', 0, 'https://ntodaynews.com/?p=1978', 0, 'post', '', 0),
(1979, 1, '2025-06-30 09:41:09', '2025-06-30 04:11:09', '', 'collector', 'Strict action will be taken against those involved in illegal collection.', 'inherit', 'open', 'closed', '', 'whatsapp-image-2025-06-30-at-09-38-17_d840e4bf', '', '', '2025-06-30 09:41:25', '2025-06-30 04:11:25', '', 1978, 'http://ntodaynews.com/wp-content/uploads/2025/06/WhatsApp-Image-2025-06-30-at-09.38.17_d840e4bf.jpg', 0, 'attachment', 'image/jpeg', 0),
