(3286, 1, '2025-11-26 19:36:49', '2025-11-26 14:06:49', '/* Hide overlay text — replace .overlay-selector with the real selector you find */\n.overlay-selector {\n  display: none !important;\n  visibility: hidden !important;\n}\n\n/* Example selectors you might try (do not add all at once unless matching) */\n.hero-caption, .post-title-overlay, .entry-hero .overlay, .featured-overlay { display:none !important; }\n.video-grid{\n  display:grid;\n  grid-template-columns:repeat(1fr);\n  gap:15px;\n  margin:15px 0;\n}\n/* ===== LIVE / LATEST SECTION ===== */\n\n.yt-live-section {\n  margin: 20px 0 30px;\n}\n\n.yt-title {\n  font-size: 20px;\n  font-weight: 700;\n  margin-bottom: 12px;\n}\n\n/* Blinking LIVE text */\n.live-blink {\n  color: red;\n  animation: blinkLive 1s infinite;\n}\n\n@keyframes blinkLive {\n  0% { opacity: 1; }\n  50% { opacity: 0.4; }\n  100% { opacity: 1; }\n}\n\n/* Video container */\n.yt-video-wrap {\n  position: relative;\n  width: 100%;\n  max-width: 100%;\n  aspect-ratio: 16 / 9;   /* 🔥 KEY FIX */\n  background: #000;\n  overflow: hidden;\n  border-radius: 6px;\n}\n\n/* iframe full fit */\n.yt-video-wrap iframe {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n}\n\n/* LIVE badge */\n.live-badge {\n  position: absolute;\n  top: 10px;\n  right: 10px;\n  background: red;\n  color: #fff;\n  font-size: 12px;\n  padding: 6px 10px;\n  border-radius: 4px;\n  font-weight: bold;\n  z-index: 10;\n}\n\n/* Mobile spacing */\n@media (max-width: 768px) {\n  .yt-title {\n    font-size: 18px;\n  }\n}\n\n.yt-video-wrap {\n  position: relative;\n}\n\n.live-badge {\n  position: absolute;\n  top: 10px;\n  right: 10px;\n  background: red;\n  color: #fff;\n  padding: 4px 8px;\n  font-size: 12px;\n  font-weight: bold;\n  z-index: 10;\n}\n\n.live-blink {\n  animation: blink 1s infinite;\n  color: red;\n  font-weight: bold;\n}\n\n@keyframes blink {\n  0% { opacity: 1; }\n  50% { opacity: .3; }\n  100% { opacity: 1; }\n}\n/* Only Telugu text apply Noto Sans Telugu */\n:lang(te),\n.post-content,\n.entry-content,\n.single-post,\n.single-post p,\n.single-post h1,\n.single-post h2,\n.single-post h3,\n.single-post h4,\n.single-post h5,\n.single-post h6 {\n    font-family: \'Noto Sans Telugu\', sans-serif;\n}\n/* Classic / Block Editor – Telugu typing font */\n.editor-styles-wrapper,\n.editor-styles-wrapper p,\n.editor-styles-wrapper h1,\n.editor-styles-wrapper h2,\n.editor-styles-wrapper h3,\n.editor-styles-wrapper h4,\n.editor-styles-wrapper h5,\n.editor-styles-wrapper h6 {\n    font-family: \'Noto Sans Telugu\', sans-serif !important;\n    font-weight: 400;\n}\n/* Header Ads Section Full Width */\n.header-ads-section,\n.header-ads,\n.header-widget-area {\n    width: 100% !important;\n    max-width: 100% !important;\n}\n\n/* Center align content inside */\n.header-ads-section .widget,\n.header-ads .widget {\n    width: 100%;\n    text-align: center;\n}\n\n/* Mobile fix */\n@media (max-width: 768px) {\n    .header-ads-section {\n        padding-left: 10px;\n        padding-right: 10px;\n    }\n}\n.site-header .container,\n.site-header .wrap {\n    max-width: 100% !important;\n}\nbody{\n    margin:0;\n    background:#cfcfcf;\n    font-family:\'Noto Serif Telugu\',\'Noto Sans Telugu\',serif;\n}\n\n/* A4 PAGE */\n.paper{\n    width:794px;\n    min-height:1123px;\n    margin:10px auto;\n    background:#fff;\n    padding:28px 30px;\n    box-sizing:border-box;\n}\n\n/* HEADER */\n.header{\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    border-bottom:2px solid #000;\n    padding-bottom:6px;\n}\n.header img{height:60px;}\n.meta{\n    font-size:13px;\n    text-align:right;\n    line-height:1.3;\n}\n\n/* HEADLINE */\n.headline{\n    font-size:40px;\n    font-weight:900;\n    margin:14px 0 10px;\n    line-height:1.15;\n}\n\n/* IMAGE */\n.photos{\n    margin:8px 0 14px;\n}\n.photos img{\n    width:100%;\n    height:auto;\n    border:1px solid #ccc;\n}\n\n/* ARTICLE */\n.article{\n    font-size:18px;\n    line-height:1.55;\n    column-count:2;\n    column-gap:22px;\n    text-align:justify;\n}\n\n.article p{\n    margin:0 0 10px;\n}\n\n/* HASHTAGS / FOLLOW */\n.article strong{\n    font-weight:700;\n}\n\n/* FOOTER */\n.footer{\n    border-top:1px solid #000;\n    margin-top:18px;\n    padding-top:6px;\n    font-size:13px;\n    text-align:center;\n}', 'color-magazine', '', 'publish', 'closed', 'closed', '', 'color-magazine', '', '', '2026-02-03 14:01:58', '2026-02-03 08:31:58', '', 0, 'https://ntodaynews.com/color-magazine/', 0, 'custom_css', '', 0),
