INSERT INTO `pctz_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(4897, 1, '2026-01-22 10:07:01', '2026-01-22 04:37:01', '<img class=\"alignnone wp-image-4896 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/01/WhatsApp-Image-2026-01-22-at-8.56.14-AM-1024x452.jpeg\" alt=\"\" width=\"640\" height=\"283\" />\r\n\r\n<span style=\"font-size: 28px; color: #ff0000;\"><strong><span style=\"font-family: noto-sans-telugi;\">బాధితులకు ఊరట: ఘటనా స్థలంలోనే ఎఫ్‌ఐఆర్‌</span></strong></span>\r\n\r\n<span style=\"color: #003300;\"><strong><span style=\"font-size: 20px; font-family: noto-sans-telugi;\">తెలంగాణ పోలీసుల చారిత్రాత్మక నిర్ణయం</span></strong></span>\r\n\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\"><span style=\"color: #ff0000;\">NTODAY NEWS:</span> <span style=\"color: #000080;\">హైదరాబాద్</span></span></strong>\r\n\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">హైదరాబాద్‌లో ‘సిటిజన్ సెంట్రిక్’ విధానం అమలు</span>\r\n\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">నేర బాధితులకు సత్వర న్యాయం అందించడమే లక్ష్యంగా తెలంగాణ పోలీస్ శాఖ మరో కీలక సంస్కరణకు శ్రీకారం చుట్టింది. బాధితులు పోలీస్ స్టేషన్‌కు వెళ్లాల్సిన అవసరం లేకుండా, నేరం జరిగిన స్థలంలోనే ఎఫ్‌ఐఆర్ నమోదు చేసే ‘విక్టిమ్/సిటిజన్ సెంట్రిక్’ విధానాన్ని హైదరాబాద్‌లో అమలు చేస్తున్నట్లు నగర పోలీస్ కమిషనర్ వీసీ సజ్జనర్ తెలిపారు.</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">బంజారాహిల్స్‌లోని కమాండ్ అండ్ కంట్రోల్ సెంటర్ (TGICCC)లో నిర్వహించిన అవగాహన సమావేశంలో ఆయన ఈ విధానం వివరించారు.</span>\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">పోలీసులే బాధితుల వద్దకు</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">నేరం జరిగిన తర్వాత బాధితులు శారీరకంగా, మానసికంగా ఆందోళనలో ఉంటారని, అటువంటి సమయంలో స్టేషన్‌కు రావడం భారంగా మారుతుందని తెలిపారు. ఈ పరిస్థితిని దృష్టిలో ఉంచుకుని తెలంగాణ సీఐడీ ఈ కొత్త విధానాన్ని రూపొందించిందన్నారు.</span>\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">ఏ కేసుల్లో స్పాట్ ఎఫ్‌ఐఆర్</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">-ఆత్మహత్యలు</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">-అసహజ మరణాలు</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">-రోడ్డు ప్రమాదాలు</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">-చోరీలు, దోపిడీలు</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">-వాహన దొంగతనాలు</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">-మహిళలు, పిల్లలపై నేరాలు</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">-ర్యాగింగ్ కేసులు</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">ఈ కేసుల్లో పోలీసులు నేరుగా బాధితుల వద్దకు వెళ్లి ఫిర్యాదు స్వీకరిస్తారు.</span>\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">ఆసుపత్రిలో ఉన్నా కేసు నమోదు</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">బాధితులు ఆసుపత్రిలో చికిత్స పొందుతున్నా, పోలీసులు అక్కడికే వెళ్లి వివరాలు సేకరించి తక్షణమే ఎఫ్‌ఐఆర్ నమోదు చేస్తారని స్పష్టం చేశారు.</span>\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">నిర్లక్ష్యం వహిస్తే కఠిన చర్యలు</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">ఈ విధానం అమలులో అలసత్వం వహించిన పోలీసులపై శాఖాపరమైన చర్యలు తప్పవని హెచ్చరించారు. బాధితులను అనవసరంగా స్టేషన్‌కు రప్పించినా, కేసు నమోదులో జాప్యం చేసినా చర్యలు తీసుకుంటామని తెలిపారు. ప్రతి కేసును ఏసీపీ, డీసీపీ స్థాయి అధికారులు పర్యవేక్షిస్తారని చెప్పారు.</span>\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">ఫిర్యాదు నమోదు కాకపోతే</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">ఈ విధానం ప్రకారం ఎఫ్‌ఐఆర్ నమోదు చేయకపోతే, బాధితులు హైదరాబాద్ సిటీ పోలీస్ అధికారిక వాట్సాప్ నంబర్ 94906 16555 కు వివరాలు పంపాలని సూచించారు.</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">సైబర్ నేర బాధితుల కోసం ప్రారంభించిన ‘సి-మిత్ర’ తరహాలోనే, ఈ విధానం కూడా ప్రజలకు రక్షణగా నిలుస్తుందని తెలిపారు. ఈ విధానాన్ని రూపొందించిన డీజీపీ బి. శివధర్ రెడ్డి, సీఐడీ అదనపు డీజీపీ చారు సిన్హాలకు కృతజ్ఞతలు తెలిపారు.</span>\r\n\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#TelanganaPolice</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#CitizenCentricPolicing</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#SpotFIR</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#HyderabadPolice</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#PoliceReforms</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#VictimSupport</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#PublicSafety</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#LawAndOrder</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#TGPolice</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#JusticeForAll</span>\r\n\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">Follow us on</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\"><a style=\"color: #000000;\" href=\"https://ntodaynews.com/\">Website</a></span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\"><a style=\"color: #000000;\" href=\"https://www.facebook.com/share/156vzUPBsQ/\">Facebook</a></span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\"><a style=\"color: #000000;\" href=\"https://www.instagram.com/ntoday_news?utm_source=qr&amp;igsh=bHp0M2x5dTIydXYy\">Instagram</a></span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\"><a style=\"color: #000000;\" href=\"https://youtube.com/@ntodaynews?si=XcGJOnHJ2MGzT0MF\">YouTube</a></span>', 'తెలంగాణ పోలీసుల చారిత్రాత్మక నిర్ణయం', '', 'inherit', 'closed', 'closed', '', '4893-revision-v1', '', '', '2026-01-22 10:07:01', '2026-01-22 04:37:01', '', 4893, 'https://ntodaynews.com/?p=4897', 0, 'revision', '', 0),
(4898, 1, '2026-01-22 21:28:53', '2026-01-22 15:58:53', '<img class=\"alignnone wp-image-4911 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/01/WhatsApp-Image-2026-01-22-at-6.38.44-PM-1024x500.jpeg\" alt=\"\" width=\"640\" height=\"313\" />\r\n\r\n<span style=\"color: #ff0000;\"><strong><span style=\"font-size: 28px; font-family: noto-sans-telugi;\">కాంగ్రెస్ హయాంలో అభివృద్ధి శూన్యం: దావ వసంత సురేష్</span></strong></span>\r\n\r\n<span style=\"color: #003300;\"><strong><span style=\"font-size: 20px; font-family: noto-sans-telugi;\">రాయికల్‌లో బీఆర్‌ఎస్ మీడియా సమావేశం</span></strong></span>\r\n\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\"><span style=\"color: #ff0000;\">NTODAY NEWS:</span> <span style=\"color: #000080;\">గొల్లపల్లి మండలం రిపోర్టర్ లక్ష్మణ్</span></span></strong>\r\n\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">రాయికల్ పట్టణ అభివృద్ధి మొత్తం బీఆర్‌ఎస్ ప్రభుత్వ హయాంలోనే జరిగిందని, ప్రస్తుత కాంగ్రెస్ ప్రభుత్వంలో కొత్తగా జరిగిన అభివృద్ధి ఏమీ లేదని జగిత్యాల జిల్లా తొలి జడ్పీ చైర్‌పర్సన్ దావ వసంత సురేష్ విమర్శించారు. గురువారం రాయికల్ పట్టణంలో బీఆర్‌ఎస్ నాయకులతో కలిసి నిర్వహించిన మీడియా సమావేశంలో ఆమె మాట్లాడారు.</span>\r\n\r\n<img class=\"alignnone wp-image-4910 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/01/WhatsApp-Image-2026-01-22-at-6.38.44-PM-1-1024x533.jpeg\" alt=\"\" width=\"640\" height=\"333\" />\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">కేసీఆర్ పాలనలోనే రాయికల్ అభివృద్ధి</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">గ్రామ పంచాయతీగా ఉన్న రాయికల్‌ను మున్సిపాలిటీగా మార్చి, రూ. 25 కోట్ల నిధులతో ప్రతి వార్డును అభివృద్ధి చేసింది కేసీఆర్ ప్రభుత్వమేనని తెలిపారు.</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">“రాయికల్ పట్టణంలో జరిగిన ప్రతి అభివృద్ధి పని బీఆర్‌ఎస్ పాలనలోనే జరిగింది. కాంగ్రెస్ ప్రభుత్వం అధికారంలోకి వచ్చాక కొత్తగా ఒక్క పని కూడా ప్రారంభించలేదు” అని ఆమె వ్యాఖ్యానించారు. గతంలో మున్సిపాలిటీలో గులాబీ జెండా ఎగురవేశామని, చేసిన అభివృద్ధిని చూసి ప్రజలు మళ్లీ బీఆర్‌ఎస్‌కే అవకాశం ఇస్తారని ధీమా వ్యక్తం చేశారు.</span>\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">ఎమ్మెల్యేపై విమర్శలు</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">అభివృద్ధి కోసమే పార్టీ మారానని చెప్పిన ఎమ్మెల్యేపై ఆమె ప్రశ్నలు సంధించారు.</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">అభివృద్ధి కోసమే పార్టీ మారితే రాయికల్–మైథాపూర్, ఇటిక్యాల బ్రిడ్జి పనులు ఎందుకు పూర్తి కాలేదని ప్రశ్నించారు.</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">కార్యకర్తల కష్టంతో గెలిచి, స్వప్రయోజనాల కోసమే పార్టీ మారారని విమర్శించారు.</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">ప్రభుత్వంతో కలిసి పని చేస్తానన్న ఎమ్మెల్యేకు గాంధీ భవన్‌లో ఏ పని ఉందని నిలదీశారు.</span>\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">హామీల అమలు ఎక్కడ?</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">కాంగ్రెస్ ప్రభుత్వం ఇచ్చిన హామీలపై ప్రజలు ఎదురుచూస్తున్నారని పేర్కొన్నారు.</span>\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">రైతు భరోసా నిధులు ఎప్పుడు జమ చేస్తారు?</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">మహాలక్ష్మి పథకం కింద మహిళలకు రూ. 2500 ఎప్పటి నుంచి ఇస్తారు?</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">పెన్షన్లు రూ. 2000 నుంచి రూ. 4000కి ఎప్పుడు పెంచుతారు?</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">బీఆర్‌ఎస్ హయాంలో మంజూరైన 60 డబుల్ బెడ్‌రూమ్ ఇళ్ల పనులు ఎందుకు నిలిపివేశారు?</span>\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">డైవర్షన్ రాజకీయాలు</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">మున్సిపల్ ఎన్నికల వేళ ప్రజల దృష్టి మళ్లించేందుకే రేవంత్ రెడ్డి ప్రభుత్వం బీఆర్‌ఎస్ నాయకులకు నోటీసులు ఇస్తూ డైవర్షన్ రాజకీయాలు చేస్తోందని ఆరోపించారు. ప్రజలు అన్నీ గమనిస్తున్నారని, రాబోయే స్థానిక సంస్థల ఎన్నికల్లో కాంగ్రెస్‌కు తగిన బుద్ధి చెబుతారని హెచ్చరించారు.</span>\r\n<strong><span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">పాల్గొన్న నాయకులు</span></strong>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">ఈ సమావేశంలో బీఆర్‌ఎస్ పట్టణ అధ్యక్షుడు ఎలిగేటి అనిల్ కుమార్, వైస్ ప్రెసిడెంట్ వాసం రాజేందర్, కోఆర్డినేటర్ తురగ శ్రీధర్ రెడ్డి, మాజీ మార్కెట్ కమిటీ చైర్మన్ ఉదయశ్రీ లింగన్న, మండల అధ్యక్షుడు బర్కాం మల్లేష్, మాజీ కౌన్సిలర్లు శ్రీరాములు, సత్యనారాయణ, మహేష్ గౌడ్, మహేందర్, వనిత గణేష్, సోహెల్, బాబా, ప్రశాంత్ రావు, లింగన్న తదితరులు పాల్గొన్నారు.</span>\r\n\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#BRSParty</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#DavaVasanthaSuresh</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#Raikal</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#TelanganaPolitics</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#CongressFailure</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#DevelopmentPolitics</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#KCR</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#LocalBodyElections</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#JagtialDistrict</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">#PoliticalNews</span>\r\n\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\">Follow us on</span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\"><a style=\"color: #000000;\" href=\"https://ntodaynews.com/\">Website</a></span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\"><a style=\"color: #000000;\" href=\"https://www.facebook.com/share/156vzUPBsQ/\">Facebook</a></span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\"><a style=\"color: #000000;\" href=\"https://www.instagram.com/ntoday_news?utm_source=qr&amp;igsh=bHp0M2x5dTIydXYy\">Instagram</a></span>\r\n<span style=\"color: #000000; font-size: 20px; font-family: noto-sans-telugi;\"><a style=\"color: #000000;\" href=\"https://youtube.com/@ntodaynews?si=XcGJOnHJ2MGzT0MF\">YouTube</a></span>', 'కాంగ్రెస్ హయాంలో అభివృద్ధి శూన్యం', '', 'publish', 'open', 'open', '', 'there-was-no-development-during-the-congress-regime', '', '', '2026-01-22 21:28:53', '2026-01-22 15:58:53', '', 0, 'https://ntodaynews.com/?p=4898', 0, 'post', '', 0),
