(5398, 1, '2026-02-02 11:25:09', '2026-02-02 05:55:09', '/* Hide overlay text — replace .overlay-selector with the real selector you find */\n.overlay-selector {\n  display: none !important;\n  visibility: hidden !important;\n}\n\n/* Example selectors you might try (do not add all at once unless matching) */\n.hero-caption, .post-title-overlay, .entry-hero .overlay, .featured-overlay { display:none !important; }\n.video-grid{\n  display:grid;\n  grid-template-columns:repeat(1fr);\n  gap:15px;\n  margin:15px 0;\n}\n/* ===== LIVE / LATEST SECTION ===== */\n\n.yt-live-section {\n  margin: 20px 0 30px;\n}\n\n.yt-title {\n  font-size: 20px;\n  font-weight: 700;\n  margin-bottom: 12px;\n}\n\n/* Blinking LIVE text */\n.live-blink {\n  color: red;\n  animation: blinkLive 1s infinite;\n}\n\n@keyframes blinkLive {\n  0% { opacity: 1; }\n  50% { opacity: 0.4; }\n  100% { opacity: 1; }\n}\n\n/* Video container */\n.yt-video-wrap {\n  position: relative;\n  width: 100%;\n  max-width: 100%;\n  aspect-ratio: 16 / 9;   /* 🔥 KEY FIX */\n  background: #000;\n  overflow: hidden;\n  border-radius: 6px;\n}\n\n/* iframe full fit */\n.yt-video-wrap iframe {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n}\n\n/* LIVE badge */\n.live-badge {\n  position: absolute;\n  top: 10px;\n  right: 10px;\n  background: red;\n  color: #fff;\n  font-size: 12px;\n  padding: 6px 10px;\n  border-radius: 4px;\n  font-weight: bold;\n  z-index: 10;\n}\n\n/* Mobile spacing */\n@media (max-width: 768px) {\n  .yt-title {\n    font-size: 18px;\n  }\n}\n\n.yt-video-wrap {\n  position: relative;\n}\n\n.live-badge {\n  position: absolute;\n  top: 10px;\n  right: 10px;\n  background: red;\n  color: #fff;\n  padding: 4px 8px;\n  font-size: 12px;\n  font-weight: bold;\n  z-index: 10;\n}\n\n.live-blink {\n  animation: blink 1s infinite;\n  color: red;\n  font-weight: bold;\n}\n\n@keyframes blink {\n  0% { opacity: 1; }\n  50% { opacity: .3; }\n  100% { opacity: 1; }\n}\n/* =====================================\n   REMOVE TEXT OVER IMAGE (NOT IMAGE)\n   WORKS FOR HOME + SINGLE\n===================================== */\n\n/* Hide overlay text only */\n.thumb-cat-wrap,\n.thumb-cat-wrap .entry-title,\n.thumb-cat-wrap .post-meta,\n.thumb-cat-wrap .post-categories,\n.thumb-cat-wrap .post-date {\n  display: none !important;\n}\n\n/* Make sure thumbnail image is visible */\n.color-magazine-post-thumbnail img,\n.post-thumbnail img {\n  display: block !important;\n  visibility: visible !important;\n  opacity: 1 !important;\n}\n\n/* Text below image should remain */\n.post-meta,\n.entry-title,\n.post-date,\n.post-categories {\n  display: block !important;\n}', 'color-magazine', '', 'inherit', 'closed', 'closed', '', '3286-revision-v1', '', '', '2026-02-02 11:25:09', '2026-02-02 05:55:09', '', 3286, 'https://ntodaynews.com/?p=5398', 0, 'revision', '', 0),
(5400, 1, '2026-02-02 11:29:34', '2026-02-02 05:59:34', '/* Hide overlay text — replace .overlay-selector with the real selector you find */\n.overlay-selector {\n  display: none !important;\n  visibility: hidden !important;\n}\n\n/* Example selectors you might try (do not add all at once unless matching) */\n.hero-caption, .post-title-overlay, .entry-hero .overlay, .featured-overlay { display:none !important; }\n.video-grid{\n  display:grid;\n  grid-template-columns:repeat(1fr);\n  gap:15px;\n  margin:15px 0;\n}\n/* ===== LIVE / LATEST SECTION ===== */\n\n.yt-live-section {\n  margin: 20px 0 30px;\n}\n\n.yt-title {\n  font-size: 20px;\n  font-weight: 700;\n  margin-bottom: 12px;\n}\n\n/* Blinking LIVE text */\n.live-blink {\n  color: red;\n  animation: blinkLive 1s infinite;\n}\n\n@keyframes blinkLive {\n  0% { opacity: 1; }\n  50% { opacity: 0.4; }\n  100% { opacity: 1; }\n}\n\n/* Video container */\n.yt-video-wrap {\n  position: relative;\n  width: 100%;\n  max-width: 100%;\n  aspect-ratio: 16 / 9;   /* 🔥 KEY FIX */\n  background: #000;\n  overflow: hidden;\n  border-radius: 6px;\n}\n\n/* iframe full fit */\n.yt-video-wrap iframe {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n}\n\n/* LIVE badge */\n.live-badge {\n  position: absolute;\n  top: 10px;\n  right: 10px;\n  background: red;\n  color: #fff;\n  font-size: 12px;\n  padding: 6px 10px;\n  border-radius: 4px;\n  font-weight: bold;\n  z-index: 10;\n}\n\n/* Mobile spacing */\n@media (max-width: 768px) {\n  .yt-title {\n    font-size: 18px;\n  }\n}\n\n.yt-video-wrap {\n  position: relative;\n}\n\n.live-badge {\n  position: absolute;\n  top: 10px;\n  right: 10px;\n  background: red;\n  color: #fff;\n  padding: 4px 8px;\n  font-size: 12px;\n  font-weight: bold;\n  z-index: 10;\n}\n\n.live-blink {\n  animation: blink 1s infinite;\n  color: red;\n  font-weight: bold;\n}\n\n@keyframes blink {\n  0% { opacity: 1; }\n  50% { opacity: .3; }\n  100% { opacity: 1; }\n}\n/* ===============================\n   COLOR MAGAZINE – FINAL FIX\n=============================== */\n\n/* FORCE thumbnails to show */\n.color-magazine-post-thumbnail,\n.color-magazine-post-thumbnail img {\n  display: block !important;\n  visibility: visible !important;\n  opacity: 1 !important;\n}\n\n/* HOME PAGE: remove text over image */\n.thumb-cat-wrap {\n  display: none !important;\n}\n\n/* SINGLE POST: remove overlay text */\n.single .thumb-cat-wrap,\n.single .thumb-cat-wrap * {\n  display: none !important;\n}\n\n/* SINGLE POST: keep image visible */\n.single .post-thumbnail img {\n  display: block !important;\n  visibility: visible !important;\n}', 'color-magazine', '', 'inherit', 'closed', 'closed', '', '3286-revision-v1', '', '', '2026-02-02 11:29:34', '2026-02-02 05:59:34', '', 3286, 'https://ntodaynews.com/?p=5400', 0, 'revision', '', 0),
