INSERT INTO `pctz_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(5412, 1, '2026-02-02 13:03:53', '2026-02-02 07:33:53', '<img class=\"alignnone wp-image-5413 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-02-at-11.50.01-AM-1024x460.jpeg\" alt=\"\" width=\"640\" height=\"288\" />\r\n\r\n<strong><span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><span style=\"color: #ff0000; font-size: 28px;\">మదనపల్లిలో మోహన్ చెస్ అకాడమీ ఓపెన్ రాపిడ్ టోర్నమెంట్</span>\r\n</span></strong>\r\n\r\n<strong><span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><span style=\"color: #003300;\">గురుకులం చెస్ క్లబ్ క్రీడాకారుల అద్భుత ప్రదర్శన</span>\r\n</span></strong>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><strong><span style=\"color: #ff0000;\">NTODAY NEWS:</span> <span style=\"color: #000080;\">అన్నమయ్య జిల్లా, పుంగనూరు</span></strong>\r\n</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">మదనపల్లిలో నిర్వహించిన మొదటి మోహన్ చెస్ అకాడమీ ఓపెన్ రాపిడ్ టోర్నమెంట్లో గురుకులం చెస్ క్లబ్‌కు చెందిన క్రీడాకారులు అద్భుత ప్రతిభ కనబరిచి పలు విభాగాల్లో బహుమతులు సాధించారు. ఈ విజయ ఫలితాలను గురుకులం చెస్ క్లబ్ గర్వంగా వెల్లడించింది.\r\n</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><strong>విజేతల వివరాలు:</strong>\r\n-అన్నమయ్య జిల్లా విభాగం – 2వ స్థానం\r\n₹700 నగదు బహుమతి, మెమెంటో\r\nACM ఎం. సతీష్ – 9వ తరగతి, ZPHS గూడూరుపల్లి\r\n</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">-రేటింగ్ లేని కేటగిరీ – 9వ స్థానం\r\n₹400 నగదు బహుమతి, మెమెంటో\r\nవిద్యార్థి – 10వ తరగతి, మున్సిపల్ హై స్కూల్, కొత్తిండ్లు (పుంగనూరు)\r\n</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">-అండర్–16 విభాగం – 3వ స్థానం\r\nట్రోఫీ\r\nటి. గౌతమ్ – 8వ తరగతి, ZPHS గూడూరుపల్లి\r\n</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">-మహిళా అండర్–16 విభాగం – 8వ స్థానం\r\nట్రోఫీ\r\nకె. సాయి నవ్యశ్రీ – 9వ తరగతి, ZPHS బాలికల పాఠశాల, పుంగనూరు\r\n</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">-మహిళా అండర్–13 విభాగం – 6వ స్థానం\r\nజి. మోక్షిత – 6వ తరగతి, AP మోడల్ స్కూల్, ఆదివినాథునికుంట (పుంగనూరు)\r\n</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">-అండర్–9 విభాగం – 4వ స్థానం\r\nట్రోఫీ\r\nఎం. సౌర్య – 3వ తరగతి, శారద విద్యా నికేతన్, పుంగనూరు\r\n</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">-అండర్–9 విభాగం – 10వ స్థానం\r\nపతకం\r\nఎల్. ప్రజ్వాన్ – 3వ తరగతి, నారాయణ పాఠశాల, పుంగనూరు\r\n</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">ఈ సందర్భంగా గురుకులం చెస్ క్లబ్ ప్రతినిధులు విజేతలందరికీ శుభాకాంక్షలు తెలియజేస్తూ, భవిష్యత్తులో ఇంకా ఉన్నత విజయాలు సాధించాలని ఆకాంక్షించారు.\r\nచిన్న వయసులోనే చెస్‌లో ప్రతిభ చూపుతున్న ఈ విద్యార్థులు పుంగనూరు ప్రాంతానికి గర్వకారణం అని వారు పేర్కొన్నారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">Follow us on</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://ntodaynews.com/\">Website</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.facebook.com/share/156vzUPBsQ/\">Facebook</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.instagram.com/ntoday_news?utm_source=qr&amp;igsh=bHp0M2x5dTIydXYy\">Instagram</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://youtube.com/@ntodaynews?si=XcGJOnHJ2MGzT0MF\">YouTube</a></span>', 'మోహన్ చెస్ అకాడమీ ఓపెన్ రాపిడ్ టోర్నమెంట్', '', 'publish', 'open', 'open', '', 'mohan-chess-academy-open-rapid-tournament', '', '', '2026-02-02 13:03:53', '2026-02-02 07:33:53', '', 0, 'https://ntodaynews.com/?p=5412', 0, 'post', '', 0),
