INSERT INTO `pctz_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(6007, 1, '2026-02-13 12:17:28', '2026-02-13 06:47:28', '<img class=\"alignnone wp-image-6004 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-13-at-10.56.14-AM-1024x491.jpeg\" alt=\"\" width=\"640\" height=\"307\" />\r\n\r\n<span style=\"color: #ff0000; font-size: 28px;\"><strong><span style=\"font-family: noto-sans-telugi;\">బాలికల వసతి గృహంలో కలెక్టర్ ఆకస్మిక తనిఖీ</span></strong></span>\r\n\r\n<strong><span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><span style=\"color: #ff0000;\">NTODAY NEWS: </span><span style=\"color: #000080;\"> పుంగనూరు ప్రతినిధి రాఘవేంద్ర రాజు </span></span></strong>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">పుంగనూరు: పుంగనూరులోని సాంఘిక సంక్షేమ బాలికల వసతి గృహాన్ని జిల్లా కలెక్టర్ నిశాంత్ కుమార్ గురువారం సాయంత్రం ఆకస్మికంగా తనిఖీ చేశారు. వసతి గృహంలో నివసిస్తూ చదువుకుంటున్న 9, 10వ తరగతి విద్యార్థినుల పాఠ్యపుస్తకాల పఠనాన్ని పరిశీలించారు.</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">ఈ సందర్భంగా కలెక్టర్ మాట్లాడుతూ బాలికల చదువుపై ప్రత్యేక దృష్టి సారించాలని సూచించారు. ముఖ్యంగా ఇంగ్లీష్, సైన్స్, గణిత శాస్త్రం వంటి విషయాలను విద్యార్థులకు సులభంగా అర్థమయ్యే విధంగా బోధించాలని ఉపాధ్యాయులకు ఆదేశించారు.</span>\r\n\r\n<img class=\"alignnone wp-image-6003 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-13-at-10.56.52-AM-1024x552.jpeg\" alt=\"\" width=\"640\" height=\"345\" />\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">వసతి గృహ పరిసరాలు పరిశుభ్రంగా ఉండేలా చూడాలని, బాత్రూములను ఎప్పటికప్పుడు శుభ్రపరచాలని, నీటి సరఫరా నిరంతరంగా ఉండేలా చర్యలు తీసుకోవాలని సూచించారు. పరిశుభ్రమైన వాతావరణం విద్యార్థినుల ఆరోగ్యం మరియు విద్యాభ్యాసానికి కీలకమని పేర్కొన్నారు.</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">వసతి గృహంలో అందిస్తున్న భోజన నాణ్యతను కూడా పరిశీలించి, మెనూ ప్రకారం పౌష్టికాహారం అందించాలని నిర్వాహకులకు ఆదేశించారు. విద్యార్థినులు అనారోగ్య సమస్యలకు గురికాకుండా తరచుగా ఏఎన్ఎంల ద్వారా కంటి పరీక్షలు మరియు ఇతర వైద్య పరీక్షలు నిర్వహించేలా చర్యలు తీసుకోవాలని సాంఘిక సంక్షేమ శాఖ అధికారులను ఆదేశించారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">#Punganur #SocialWelfareHostel #CollectorInspection #GirlsEducation #StudentWelfare #AndhraPradeshNews</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">Follow us on</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://ntodaynews.com/\">Website</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.facebook.com/share/156vzUPBsQ/\">Facebook</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.instagram.com/ntoday_news?utm_source=qr&amp;igsh=bHp0M2x5dTIydXYy\">Instagram</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://youtube.com/@ntodaynews?si=XcGJOnHJ2MGzT0MF\">YouTube</a></span>', 'వసతి గృహంలో కలెక్టర్ ఆకస్మిక తనిఖీ', '', 'inherit', 'closed', 'closed', '', '6000-revision-v1', '', '', '2026-02-13 12:17:28', '2026-02-13 06:47:28', '', 6000, 'https://ntodaynews.com/?p=6007', 0, 'revision', '', 0),
(6008, 1, '2026-02-13 12:22:43', '2026-02-13 06:52:43', '<img class=\"alignnone wp-image-6001 size-full\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-13-at-10.06.55-AM.jpeg\" alt=\"\" width=\"720\" height=\"355\" />\r\n\r\n<span style=\"font-size: 28px; color: #ff0000;\"><strong><span style=\"font-family: noto-sans-telugi;\">లక్షెట్టిపేటలో విషాదం: కౌంటింగ్ రోజే బీజేపీ అభ్యర్థి ఎల్లమ్మ మృతి</span></strong></span>\r\n\r\n<strong><span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><span style=\"color: #ff0000;\">NTODAY NEWS:</span><span style=\"color: #000080;\"> మంచిర్యాల ప్రతినిధి శ్రీనివాస్ </span></span></strong>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">మంచిర్యాల జిల్లా లక్షెట్టిపేట మున్సిపల్ ఎన్నికల ఓట్ల లెక్కింపు రోజున విషాద ఘటన చోటుచేసుకుంది. 10వ వార్డు నుంచి బీజేపీ అభ్యర్థిగా పోటీ చేసిన ఎల్లమ్మ అనారోగ్యంతో శుక్రవారం మరణించారు.</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">గత కొంతకాలంగా అనారోగ్యంతో బాధపడుతున్న ఎల్లమ్మ పరిస్థితి కౌంటింగ్ సమయంలో విషమించడంతో ఆసుపత్రిలో చికిత్స పొందుతూ తుదిశ్వాస విడిచారు. ఫలితాల ఉత్కంఠ నడుమ ఆమె మృతి వార్త తెలిసి కుటుంబ సభ్యులు, పార్టీ కార్యకర్తలు తీవ్ర విషాదంలో మునిగిపోయారు. స్థానిక నాయకులు కౌంటింగ్ కేంద్రం వద్ద మౌనం పాటించి నివాళులర్పించారు.</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">ఎన్నికల ప్రక్రియపై అధికారుల స్పష్టం</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">అభ్యర్థి మరణించినప్పటికీ పోలింగ్ ఇప్పటికే పూర్తయినందున ఓట్ల లెక్కింపు ప్రక్రియ యథావిధిగా కొనసాగుతుందని అధికారులు తెలిపారు. ఒకవేళ ఎల్లమ్మ విజయం సాధించినట్లయితే, నిబంధనల ప్రకారం ఆ వార్డు స్థానాన్ని ఖాళీగా ప్రకటించి ఉపఎన్నిక నిర్వహిస్తారు. ఇతర అభ్యర్థి మెజారిటీ సాధిస్తే, ఆయన్ను/ఆమెను విజేతగా ప్రకటిస్తారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">#Luxettipet #Mancherial #MunicipalElections #BJP #ElectionCounting #TelanganaNews #BreakingNews #LocalNews</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">Follow us on</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://ntodaynews.com/\">Website</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.facebook.com/share/156vzUPBsQ/\">Facebook</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.instagram.com/ntoday_news?utm_source=qr&amp;igsh=bHp0M2x5dTIydXYy\">Instagram</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://youtube.com/@ntodaynews?si=XcGJOnHJ2MGzT0MF\">YouTube</a></span>', 'కౌంటింగ్ రోజే బీజేపీ అభ్యర్థి మృతి', '', 'publish', 'open', 'open', '', 'bjp-candidate-dies-on-counting-day', '', '', '2026-02-13 12:22:43', '2026-02-13 06:52:43', '', 0, 'https://ntodaynews.com/?p=6008', 0, 'post', '', 0),
(6009, 1, '2026-02-13 12:22:43', '2026-02-13 06:52:43', '<img class=\"alignnone wp-image-6001 size-full\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-13-at-10.06.55-AM.jpeg\" alt=\"\" width=\"720\" height=\"355\" />\r\n\r\n<span style=\"font-size: 28px; color: #ff0000;\"><strong><span style=\"font-family: noto-sans-telugi;\">లక్షెట్టిపేటలో విషాదం: కౌంటింగ్ రోజే బీజేపీ అభ్యర్థి ఎల్లమ్మ మృతి</span></strong></span>\r\n\r\n<strong><span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><span style=\"color: #ff0000;\">NTODAY NEWS:</span><span style=\"color: #000080;\"> మంచిర్యాల ప్రతినిధి శ్రీనివాస్ </span></span></strong>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">మంచిర్యాల జిల్లా లక్షెట్టిపేట మున్సిపల్ ఎన్నికల ఓట్ల లెక్కింపు రోజున విషాద ఘటన చోటుచేసుకుంది. 10వ వార్డు నుంచి బీజేపీ అభ్యర్థిగా పోటీ చేసిన ఎల్లమ్మ అనారోగ్యంతో శుక్రవారం మరణించారు.</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">గత కొంతకాలంగా అనారోగ్యంతో బాధపడుతున్న ఎల్లమ్మ పరిస్థితి కౌంటింగ్ సమయంలో విషమించడంతో ఆసుపత్రిలో చికిత్స పొందుతూ తుదిశ్వాస విడిచారు. ఫలితాల ఉత్కంఠ నడుమ ఆమె మృతి వార్త తెలిసి కుటుంబ సభ్యులు, పార్టీ కార్యకర్తలు తీవ్ర విషాదంలో మునిగిపోయారు. స్థానిక నాయకులు కౌంటింగ్ కేంద్రం వద్ద మౌనం పాటించి నివాళులర్పించారు.</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">ఎన్నికల ప్రక్రియపై అధికారుల స్పష్టం</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">అభ్యర్థి మరణించినప్పటికీ పోలింగ్ ఇప్పటికే పూర్తయినందున ఓట్ల లెక్కింపు ప్రక్రియ యథావిధిగా కొనసాగుతుందని అధికారులు తెలిపారు. ఒకవేళ ఎల్లమ్మ విజయం సాధించినట్లయితే, నిబంధనల ప్రకారం ఆ వార్డు స్థానాన్ని ఖాళీగా ప్రకటించి ఉపఎన్నిక నిర్వహిస్తారు. ఇతర అభ్యర్థి మెజారిటీ సాధిస్తే, ఆయన్ను/ఆమెను విజేతగా ప్రకటిస్తారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">#Luxettipet #Mancherial #MunicipalElections #BJP #ElectionCounting #TelanganaNews #BreakingNews #LocalNews</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">Follow us on</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://ntodaynews.com/\">Website</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.facebook.com/share/156vzUPBsQ/\">Facebook</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.instagram.com/ntoday_news?utm_source=qr&amp;igsh=bHp0M2x5dTIydXYy\">Instagram</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://youtube.com/@ntodaynews?si=XcGJOnHJ2MGzT0MF\">YouTube</a></span>', 'కౌంటింగ్ రోజే బీజేపీ అభ్యర్థి మృతి', '', 'inherit', 'closed', 'closed', '', '6008-revision-v1', '', '', '2026-02-13 12:22:43', '2026-02-13 06:52:43', '', 6008, 'https://ntodaynews.com/?p=6009', 0, 'revision', '', 0),
(6010, 1, '2026-02-13 14:16:10', '2026-02-13 08:46:10', '<img class=\"alignnone wp-image-6011 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-13-at-1.48.40-PM-e1770972059737-1024x596.jpeg\" alt=\"\" width=\"640\" height=\"373\" />\r\n\r\n<span style=\"color: #ff0000; font-size: 28px;\"><strong><span style=\"font-family: noto-sans-telugi;\">ఉచిత క్యూ లైన్ ద్వారా శ్రీశైలం దర్శనం చేసిన జిల్లా కలెక్టర్</span></strong></span>\r\n\r\n<strong><span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><span style=\"color: #ff0000;\">NTODAY NEWS:</span><span style=\"color: #000080;\"> శ్రీశైలం / నంద్యాల జిల్లా ప్రతినిధి మల్లికార్జున్  </span></span></strong>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"> శ్రీశైలం : మహాశివరాత్రి బ్రహ్మోత్సవాల సందర్భంగా శ్రీశైలం మహా పుణ్యక్షేత్రంలోని శ్రీ భ్రమరాంబ మల్లికార్జున స్వామి దేవస్థానంలో జిల్లా కలెక్టర్ రాజకుమారి గణియా ఉచిత క్యూ లైన్ ద్వారా సాధారణ భక్తులతో కలిసి దర్శనం చేశారు. సుమారు 20 నిమిషాల్లో స్వామివారి దర్శనం పూర్తి చేశారు.</span>\r\n\r\n<img class=\"alignnone wp-image-6015 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-13-at-1.48.35-PM-1024x682.jpeg\" alt=\"\" width=\"640\" height=\"426\" /> <img class=\"alignnone wp-image-6014 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-13-at-1.48.36-PM-1024x682.jpeg\" alt=\"\" width=\"640\" height=\"426\" />\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">దర్శనం అనంతరం భక్తులకు కల్పిస్తున్న సదుపాయాలను కలెక్టర్ పరిశీలించారు. ఉచిత దర్శన క్యూ లైన్ల నిర్వహణ, భద్రతా చర్యలు, తాగునీరు, శానిటేషన్, వైద్య సదుపాయాలపై సంబంధిత అధికారులతో సమీక్ష నిర్వహించారు.</span>\r\n\r\n<img class=\"alignnone wp-image-6012 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-13-at-1.48.38-PM-1024x682.jpeg\" alt=\"\" width=\"640\" height=\"426\" /> <img class=\"alignnone wp-image-6013 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-13-at-1.48.36-PM-1-1024x682.jpeg\" alt=\"\" width=\"640\" height=\"426\" />\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">భక్తులకు ఎలాంటి అసౌకర్యం కలగకుండా అన్ని శాఖలు సమన్వయంతో పనిచేయాలని ఆదేశించారు. క్యూ లైన్లలో ఉన్న భక్తులను కలుసుకుని వారి అభిప్రాయాలను తెలుసుకున్నారు.</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">సాధారణ భక్తులకు ప్రాధాన్యత ఇస్తూ ఉచిత క్యూ లైన్ ద్వారా దర్శనం కల్పించడాన్ని దేవస్థాన అధికారులు కొనసాగిస్తున్నారని తెలిపారు. భక్తులు నియమ నిబంధనలు పాటిస్తూ ప్రశాంతంగా దర్శనం చేసుకోవాలని సూచించారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">#Srisailam #BhramarambaMallikarjuna #MahaShivaratri #TempleVisit #DistrictCollector #Nandyal #AndhraPradesh #TempleAdministration</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">Follow us on</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://ntodaynews.com/\">Website</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.facebook.com/share/156vzUPBsQ/\">Facebook</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.instagram.com/ntoday_news?utm_source=qr&amp;igsh=bHp0M2x5dTIydXYy\">Instagram</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://youtube.com/@ntodaynews?si=XcGJOnHJ2MGzT0MF\">YouTube</a></span>', 'శ్రీశైలం దర్శనం చేసిన జిల్లా కలెక్టర్', '', 'publish', 'open', 'open', '', 'district-collector-visits-srisailam', '', '', '2026-02-13 14:16:10', '2026-02-13 08:46:10', '', 0, 'https://ntodaynews.com/?p=6010', 0, 'post', '', 0),
