INSERT INTO `pctz_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(6835, 1, '2026-02-27 11:06:11', '2026-02-27 05:36:11', '<img class=\"alignnone wp-image-6834 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-27-at-10.54.39-AM-1024x449.jpeg\" alt=\"\" width=\"640\" height=\"281\" />\r\n\r\n<span style=\"font-size: 28px; color: #ff0000;\"><strong><span style=\"font-family: noto-sans-telugi;\">దళితుల ఉన్నత విద్యే లక్ష్యం: త్వరలో ‘అంబేద్కర్ టవర్’</span></strong></span>\r\n\r\n<span style=\"font-size: 20px;\"><strong><span style=\"font-family: noto-sans-telugi; color: #000000;\"><span style=\"color: #ff0000;\">NTODAY NEWS:</span> <span style=\"color: #000080;\">హైదరాబాద్</span></span></strong></span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">హైదరాబాద్‌లోనే ఢిల్లీ స్థాయి సివిల్స్ కోచింగ్ – మంత్రి అడ్లూరి లక్ష్మణ్ కుమార్ వెల్లడి</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">హైదరాబాద్: ప్రతిభావంతులైన దళిత విద్యార్థులు అన్ని రంగాల్లో రాణించాలంటే నాణ్యమైన విద్యే ప్రధాన మార్గమని రాష్ట్ర ఎస్సీ, ఎస్టీ సంక్షేమ శాఖ మంత్రి అడ్లూరి లక్ష్మణ్ కుమార్ పేర్కొన్నారు. ముఖ్యమంత్రి రేవంత్ రెడ్డి నాయకత్వంలోని ప్రభుత్వం దళితులకు కార్పొరేట్ స్థాయి విద్యను అందించడమే లక్ష్యంగా పనిచేస్తోందని తెలిపారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">బుధవారం 59 దళిత కులాల సంఘాల నాయకులతో కలిసి మంత్రి లోయర్ ట్యాంక్ బండ్‌లోని అంబేద్కర్ భవన్, కాచిగూడలోని ఎస్సీ హాస్టల్‌ను సందర్శించారు. ఈ సందర్భంగా విద్యార్థుల కోసం చేపట్టనున్న కీలక నిర్ణయాలను ప్రకటించారు.</span>\r\n\r\n<strong><span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">కీలక ప్రకటనలు</span></strong>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">మోడర్న్ కోచింగ్ హబ్: లోయర్ ట్యాంక్ బండ్‌లోని అంబేద్కర్ భవన్‌ను అత్యాధునిక కోచింగ్ హబ్‌గా అభివృద్ధి చేస్తారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">రెసిడెన్షియల్ అకాడమిక్ సెంటర్: కాచిగూడ హాస్టల్ కాంప్లెక్స్‌ను పూర్తిస్థాయి రెసిడెన్షియల్ అకాడమిక్ సెంటర్‌గా మార్చనున్నారు.</span>\r\n\r\n<img class=\"alignnone wp-image-6833 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-27-at-10.54.39-AM-1-1024x449.jpeg\" alt=\"\" width=\"640\" height=\"281\" />\r\n\r\n&nbsp;\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">హైదరాబాద్‌లోనే ఢిల్లీ స్థాయి శిక్షణ: సివిల్స్ కోచింగ్ కోసం ఢిల్లీ వెళ్లాల్సిన అవసరం లేకుండా అదే స్థాయి నాణ్యమైన శిక్షణను ఇక్కడే ఉచితంగా అందించనున్నారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">తమిళనాడు మోడల్: తమిళనాడు తరహాలో ఆధునిక సదుపాయాలతో కొత్త భవనాలు నిర్మించనున్నారు.</span>\r\n\r\n<strong><span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">అభ్యర్థులకు లభించే సదుపాయాలు</span></strong>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><strong>శిక్షణ-</strong> సివిల్స్, గ్రూప్-1, గ్రూప్-2 పోటీ పరీక్షలకు నాణ్యమైన కోచింగ్</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><strong>సాంకేతికత-</strong> డిజిటల్ లైబ్రరీలు, స్మార్ట్ క్లాస్‌రూమ్‌లు</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><strong>గైడెన్స్-</strong> రిటైర్డ్ సివిల్ సర్వెంట్స్, అనుభవజ్ఞులైన ఫ్యాకల్టీ గెస్ట్ లెక్చర్స్</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><strong>ప్రాక్టీస్-</strong> మాక్ టెస్టులు, ఇంటర్వ్యూ గైడెన్స్, పర్సనాలిటీ డెవలప్‌మెంట్</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><strong>వసతి-</strong> హాస్టల్, మెస్, స్టడీ హాల్స్ సదుపాయం</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">“పేద విద్యార్థిని గొప్ప పరిపాలకుడిగా తీర్చిదిద్దాలనే సంకల్పంతో ప్రభుత్వం ముందుకు సాగుతోంది. గ్రామీణ విద్యార్థులకు అడ్మిషన్లలో ప్రత్యేక ప్రాధాన్యత ఉంటుంది,” అని మంత్రి తెలిపారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">త్వరలో ఈ కోచింగ్ సెంటర్లను రాష్ట్రంలోని ప్రతి జిల్లాకు విస్తరించే దిశగా చర్యలు తీసుకుంటామని పేర్కొన్నారు. కార్యక్రమంలో ఎమ్మెల్సీ అద్దంకి దయాకర్, మాజీ మంత్రి మోత్కుపల్లి నర్సింహులు మరియు వివిధ దళిత సంఘాల నాయకులు పాల్గొన్నారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">#Hyderabad #AmbedkarTower #SCSTWelfare #CivilServicesCoaching #TelanganaGovernment</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">Follow us on</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://ntodaynews.com/\">Website</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.facebook.com/share/156vzUPBsQ/\">Facebook</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.instagram.com/ntoday_news?utm_source=qr&amp;igsh=bHp0M2x5dTIydXYy\">Instagram</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://youtube.com/@ntodaynews?si=XcGJOnHJ2MGzT0MF\">YouTube</a></span>', 'దళితుల ఉన్నత విద్యే లక్ష్యం', '', 'inherit', 'closed', 'closed', '', '6831-revision-v1', '', '', '2026-02-27 11:06:11', '2026-02-27 05:36:11', '', 6831, 'https://ntodaynews.com/?p=6835', 0, 'revision', '', 0),
(6836, 1, '2026-02-27 11:39:01', '2026-02-27 06:09:01', '<img class=\"alignnone wp-image-6838 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-27-at-11.11.26-AM-1-1024x495.jpeg\" alt=\"\" width=\"640\" height=\"309\" />\r\n\r\n<span style=\"color: #ff0000;\"><strong><span style=\"font-family: noto-sans-telugi; font-size: 28px;\">సీఎం కప్‌లో జగిత్యాల క్రీడాకారుల జైత్రయాత్ర</span></strong></span>\r\n\r\n<span style=\"color: #ff0000; font-size: 20px;\"><strong><span style=\"font-family: noto-sans-telugi;\">NTODAY NEWS: <span style=\"color: #000080;\">గొల్లపల్లి ప్రతినిధి లక్ష్మణ్ </span></span></strong></span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">విజేతలను అభినందించిన ఎమ్మెల్యే డా. సంజయ్ కుమార్</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">హైదరాబాద్‌లోని గచ్చిబౌలి ఇండోర్ స్టేడియంలో నిర్వహించిన రెండవ ఎడిషన్ సీఎం కప్ రాష్ట్రస్థాయి కిక్ బాక్సింగ్ ఛాంపియన్‌షిప్‌లో జగిత్యాల జిల్లా క్రీడాకారులు ప్రతిభ చాటారు. పతకాలు సాధించిన విజేతలను జగిత్యాల ఎమ్మెల్యే డాక్టర్ సంజయ్ కుమార్ అభినందించారు.</span>\r\n\r\n<img class=\"alignnone wp-image-6839 size-large\" src=\"http://ntodaynews.com/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-27-at-11.11.26-AM-1024x463.jpeg\" alt=\"\" width=\"640\" height=\"289\" />\r\n\r\n<strong><span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">పతక విజేతలు</span></strong>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">రాష్ట్రస్థాయి పోటీల్లో మెరిసిన క్రీడాకారులు:</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">ఏ. హర్షిత్ – బంగారు పతకం</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">పి. కృష్ణ – బంగారు పతకం</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">ఆర్. అక్షయ్ – వెండి పతకం</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">ఎం. సాయి సృజన్ – కాంస్య పతకం</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">బి. కనిష్క్ – కాంస్య పతకం</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">ఎమ్మెల్యే అభినందనలు</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">ఈ సందర్భంగా ఎమ్మెల్యే మాట్లాడుతూ క్రీడల్లో క్రమశిక్షణ, పట్టుదలతో ముందుకు సాగితే ఉన్నత శిఖరాలను అధిరోహించవచ్చని పేర్కొన్నారు. జిల్లాకు ఖ్యాతి తీసుకొచ్చిన క్రీడాకారులకు భవిష్యత్తులో మరిన్ని విజయాలు అందాలని ఆకాంక్షించారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">ఈ కార్యక్రమంలో డీవైఎస్ఓ రవికుమార్, సమీండ్ల శ్రీనివాస్, గన్నె రాజిరెడ్డి, జగిత్యాల జిల్లా కిక్ బాక్సింగ్ అసోసియేషన్ అధ్యక్షుడు డాక్టర్ మోర సుమన్ కుమార్, ప్రధాన కార్యదర్శి రామాంజనేయులు, కోశాధికారి సంతోష్, కోచ్ గణేష్ పాల్గొన్నారు. ఆకుల మల్లేశం, సర్పంచుల ఫోరమ్ అధ్యక్షుడు మోహన్, తిరుమలయ్యా, శేఖర్, మోహన్ రెడ్డి, కూతురు రాజేష్, హరీష్ తదితరులు హాజరై క్రీడాకారులను అభినందించారు.</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">— గొల్లపల్లి ప్రతినిధి లక్ష్మణ్</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">#Jagtial #CMCup #KickBoxing #SportsAchievement #TelanganaSports</span>\r\n\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\">Follow us on</span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://ntodaynews.com/\">Website</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.facebook.com/share/156vzUPBsQ/\">Facebook</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://www.instagram.com/ntoday_news?utm_source=qr&amp;igsh=bHp0M2x5dTIydXYy\">Instagram</a></span>\r\n<span style=\"font-family: noto-sans-telugi; font-size: 20px; color: #000000;\"><a style=\"color: #000000;\" href=\"https://youtube.com/@ntodaynews?si=XcGJOnHJ2MGzT0MF\">YouTube</a></span>', 'సీఎం కప్‌లో జగిత్యాల క్రీడాకారుల జైత్రయాత్ర', '', 'publish', 'open', 'open', '', 'jagityala-players-triumphant-march-in-cm-cup', '', '', '2026-02-27 11:39:01', '2026-02-27 06:09:01', '', 0, 'https://ntodaynews.com/?p=6836', 0, 'post', '', 0),
